        // kit comment make the emitter's "generated code must not reference it" guard vacuous.
        /// <summary>Twin of the live widget's swatch-rim rule. The 1px rim is drawn OVER the swatch's own
        /// color, so on a NEAR-BLACK swatch a fixed 16% white composites to almost exactly the editor's panel
        /// grey — the rim reads as BACKGROUND and the swatch looks a pixel narrower each side than its light
        /// neighbours, whose rim vanishes into their own fill. (Measured: fill #191724 → rim #3E3C47 at
        /// luminance 0.243, panel 0.241.) A rim may blend into the FILL; it must never blend into the PANEL,
        /// and only a LIGHTENING rim can, so the ramp is dark-skin only. Swatches at or above 0.35 luminance
        /// keep the shipped 16% exactly, so everything that already read correctly is unchanged.</summary>
        public static Color SwatchRim(Color c)
        {
            if (IsLight) return new Color(0f, 0f, 0f, 0.45f);
            float lum = 0.299f * c.r + 0.587f * c.g + 0.114f * c.b;
            return new Color(1f, 1f, 1f, Mathf.Lerp(0.42f, 0.16f, Mathf.Clamp01(lum / 0.35f)));
        }

